<?php
namespace App\Http\Controllers\Accounting;use App\Http\Controllers\Controller;use App\Models\{Account,Folio,JournalLine,SupplierInvoice};use Illuminate\Http\Request;
class ReportsController extends Controller{public function index(Request $r){$p=auth()->user()->property_id;$to=$r->date('to')?->toDateString()??now()->toDateString();$accounts=Account::where('property_id',$p)->with(['lines'=>fn($q)=>$q->whereHas('entry',fn($e)=>$e->where('status','posted')->whereDate('entry_date','<=',$to))])->orderBy('code')->get();$trial=$accounts->map(function($a){$d=$a->lines->sum('debit');$c=$a->lines->sum('credit');return['code'=>$a->code,'name'=>$a->name,'type'=>$a->type,'debit'=>(float)$d,'credit'=>(float)$c,'balance'=>(float)$d-(float)$c];});$income=$trial->where('type','income')->sum(fn($r)=>-$r['balance']);$expenses=$trial->where('type','expense')->sum(fn($r)=>$r['balance']);$assets=$trial->where('type','asset')->sum(fn($r)=>$r['balance']);$liabilities=$trial->where('type','liability')->sum(fn($r)=>-$r['balance']);$equity=$trial->where('type','equity')->sum(fn($r)=>-$r['balance']);return view('accounting.reports',['trial'=>$trial,'to'=>$to,'income'=>$income,'expenses'=>$expenses,'netProfit'=>$income-$expenses,'assets'=>$assets,'liabilities'=>$liabilities,'equity'=>$equity,'receivables'=>Folio::with('guest')->where('property_id',$p)->where('balance','>',0)->orderByDesc('balance')->get(),'payables'=>SupplierInvoice::with('supplier')->where('property_id',$p)->whereIn('status',['unpaid','part_paid'])->get()]);}}
